    _e("Oberon allowed: {allowed_min}–{allowed_max} MHz · configured endpoints: {minimum}–{maximum} MHz · persistent YAML: {persistent}.", "Permitido por Oberon: {allowed_min}–{allowed_max} MHz · extremos configurados: {minimum}–{maximum} MHz · YAML persistente: {persistent}.", "Permitido pelo Oberon: {allowed_min}–{allowed_max} MHz · extremos configurados: {minimum}–{maximum} MHz · YAML persistente: {persistent}.", "Oberon допускает: {allowed_min}–{allowed_max} МГц · настроено: {minimum}–{maximum} МГц · постоянный YAML: {persistent}.", "Oberon дозволяє: {allowed_min}–{allowed_max} МГц · налаштовано: {minimum}–{maximum} МГц · постійний YAML: {persistent}.", "Oberon erlaubt: {allowed_min}–{allowed_max} MHz · Endpunkte: {minimum}–{maximum} MHz · dauerhaftes YAML: {persistent}."),
    _e("Requested {floor} MHz, while D-Bus currently allows {minimum}–{maximum} MHz.", "Se solicitaron {floor} MHz, pero D-Bus permite actualmente {minimum}–{maximum} MHz.", "Foram solicitados {floor} MHz, mas o D-Bus permite atualmente {minimum}–{maximum} MHz.", "Запрошено {floor} МГц, но D-Bus сейчас допускает {minimum}–{maximum} МГц.", "Запитано {floor} МГц, але D-Bus зараз дозволяє {minimum}–{maximum} МГц.", "Angefordert: {floor} MHz; D-Bus erlaubt derzeit {minimum}–{maximum} MHz."),
